use crate::*;
type Point=[f64;2];
#[derive(Clone)]struct Face{p:[f64;3],poly:Vec<Point>}
fn clip(poly:&[Point],a:f64,b:f64,c:f64)->Vec<Point>{let mut out=vec![];if poly.is_empty(){return out}for i in 0..poly.len(){let p=poly[i];let q=poly[(i+1)%poly.len()];let fp=a*p[0]+b*p[1]+c;let fq=a*q[0]+b*q[1]+c;if fp<=1e-8{out.push(p)}if (fp<0.)!=(fq<0.){let t=fp/(fp-fq);out.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])]);}}out.dedup_by(|a,b|near(a[0],b[0])&&near(a[1],b[1]));out}
fn rect(x:f64,z:f64,w:f64,d:f64)->Vec<Point>{vec![[x,z],[w,z],[w,d],[x,d]]}
fn area(p:&[Point])->f64{(0..p.len()).map(|i|p[i][0]*p[(i+1)%p.len()][1]-p[(i+1)%p.len()][0]*p[i][1]).sum::<f64>().abs()/2.}
fn min_faces(poly:&[Point],planes:&[[f64;3]])->Vec<Face>{planes.iter().enumerate().filter_map(|(i,p)|{let mut q=poly.to_vec();for(j,v)in planes.iter().enumerate(){if i!=j{q=clip(&q,p[0]-v[0],p[1]-v[1],p[2]-v[2]);}}if area(&q)>1e-6{Some(Face{p:*p,poly:q})}else{None}}).collect()}
fn faces(c:&Config,over:f64)->Vec<Face>{let(w,d,p)=(c.width,c.depth,c.pitch/12.);let kind=architecture::preset(&c.home_style).3;let domain=rect(-over,-over,w+over,d+over);match kind{
 "Hip"=>min_faces(&domain,&[[p,0.,0.],[-p,0.,w*p],[0.,p,0.],[0.,-p,d*p]]),
 "Front gable"=>min_faces(&domain,&[[p,0.,0.],[-p,0.,w*p]]),
 "Low slope"|"Shed"=>vec![Face{p:[0.,p,0.],poly:domain}],
 "Gambrel"=>{let lower=p*1.8;let upper=p*0.45;let k=(lower-upper)*d*0.25;min_faces(&domain,&[[0.,lower,0.],[0.,upper,k],[0.,-upper,upper*d+k],[0.,-lower,lower*d]])},
 "Clipped gable"=>min_faces(&domain,&[[0.,p,0.],[0.,-p,d*p],[p,0.,d*p*0.32],[-p,0.,w*p+d*p*0.32]]),
 "Queen Anne"=>{let hip=[[p,0.,0.],[-p,0.,w*p],[0.,p,0.],[0.,-p,d*p]];let mut front=min_faces(&rect(-over,-over,w+over,d/2.),&hip);for(cx,half)in[(w*0.72,(w*0.24).min(d*0.38)),(w*0.22,(w*0.16).min(d*0.27))]{let peak=half*p;let wing=[[p,0.,peak-cx*p],[-p,0.,peak+cx*p]];let mut next=vec![];for f in front{for v in min_faces(&f.poly,&wing){let raised=clip(&v.poly,f.p[0]-v.p[0],f.p[1]-v.p[1],f.p[2]-v.p[2]);let retained=clip(&v.poly,v.p[0]-f.p[0],v.p[1]-f.p[1],v.p[2]-f.p[2]);if area(&raised)>1e-6{next.push(Face{p:v.p,poly:raised})}if area(&retained)>1e-6{next.push(Face{p:f.p,poly:retained})}}}front=next;}front.extend(min_faces(&rect(-over,d/2.,w+over,d+over),&hip));front},
 "Cross gable"=>{let cx=w*if c.home_style=="Modern farmhouse"{0.5}else if c.home_style=="Tudor"{0.3}else{0.7};let half=(w*0.30).min(d*0.42);let peak=half*p;let wing=[[p,0.,peak-cx*p],[-p,0.,peak+cx*p]];let front=rect(-over,-over,w+over,d/2.);let main=[0.,p,0.];let mut out=vec![Face{p:[0.,-p,d*p],poly:rect(-over,d/2.,w+over,d+over)}];for f in min_faces(&front,&wing){let a=clip(&f.poly,main[0]-f.p[0],main[1]-f.p[1],main[2]-f.p[2]);let b=clip(&f.poly,f.p[0]-main[0],f.p[1]-main[1],f.p[2]-main[2]);if area(&a)>1e-6{out.push(Face{p:f.p,poly:a})}if area(&b)>1e-6{out.push(Face{p:main,poly:b})}}out},
 _=>min_faces(&domain,&[[0.,p,0.],[0.,-p,d*p]])}}
pub fn height(c:&Config,x:f64,z:f64)->f64{let(w,d,p)=(c.width,c.depth,c.pitch/12.);match architecture::preset(&c.home_style).3{"Hip"=>x.min(w-x).min(z).min(d-z)*p,"Front gable"=>x.min(w-x)*p,"Low slope"|"Shed"=>z*p,"Gambrel"=>{let run=z.min(d-z);(run*p*1.8).min(run*p*0.45+(p*1.8-p*0.45)*d*0.25)},"Clipped gable"=>(z.min(d-z)*p).min((x.min(w-x)+d*0.32)*p),"Queen Anne"=>{let main=x.min(w-x).min(z).min(d-z)*p;if z>d/2.{main}else{main.max((w*0.24).min(d*0.38)*p-(x-w*0.72).abs()*p).max((w*0.16).min(d*0.27)*p-(x-w*0.22).abs()*p)}},"Cross gable"=>{let main=z.min(d-z)*p;if z>d/2.{main}else{let cx=w*if c.home_style=="Modern farmhouse"{0.5}else if c.home_style=="Tudor"{0.3}else{0.7};main.max((w*0.30).min(d*0.42)*p-(x-cx).abs()*p)}},_=>z.min(d-z)*p}}
pub fn wall_profile(c:&Config,w:&Wall)->Vec<Point>{if c.stories==2&&c.active_floor==0{return vec![[0.,0.],[w.length,0.]]}let mut ats=vec![0.,w.length];for f in faces(c,0.){for p in f.poly{if near(if w.axis=="x"{p[1]}else{p[0]},if w.axis=="x"{w.z}else{w.x}){let at=if w.axis=="x"{p[0]-w.x}else{p[1]-w.z};if at>0.&&at<w.length{ats.push(at)}}}}ats.sort_by(f64::total_cmp);ats.dedup_by(|a,b|near(*a,*b));ats.into_iter().map(|at|[at,height(c,w.x+if w.axis=="x"{at}else{0.},w.z+if w.axis=="z"{at}else{0.}).max(0.)]).collect()}
pub fn build(c:&Config)->Value{build_with_overhang(c,1.5)}
pub fn build_with_overhang(c:&Config,overhang:f64)->Value{let fs=faces(c,overhang);let mut facets=vec![];let mut rafters=vec![];let mut edges:Vec<Value>=vec![];let vertices:Vec<Point>=fs.iter().flat_map(|f|f.poly.clone()).collect();let mut seen=std::collections::BTreeSet::new();let mut area_total=0.;let mut ridge=0.;let mut hip=0.;let mut valley=0.;let mut eave=0.;let mut rake=0.;let mut rise:f64=0.;
 for(i,f)in fs.iter().enumerate(){let [a,b,k]=f.p;let surface=area(&f.poly)*(1.+a*a+b*b).sqrt();area_total+=surface;let xyz=|p:Point|[p[0],c.wall_height+a*p[0]+b*p[1]+k,p[1]];let points:Vec<_>=f.poly.iter().map(|p|{rise=rise.max(a*p[0]+b*p[1]+k);xyz(*p)}).collect();facets.push(json!({"id":format!("roof-{}",i),"points":points,"plane":f.p,"area":surface}));
  let run_x=a.abs()>b.abs();let axis=if run_x{1}else{0};let lo=f.poly.iter().map(|p|p[axis]).fold(f64::INFINITY,f64::min);let hi=f.poly.iter().map(|p|p[axis]).fold(f64::NEG_INFINITY,f64::max);let spacing=16./12.;let mut station=(lo/spacing).ceil()*spacing;while station<hi+1e-6{let mut hits=vec![];for j in 0..f.poly.len(){let p=f.poly[j];let q=f.poly[(j+1)%f.poly.len()];if (p[axis]-q[axis]).abs()<1e-8{if near(station,p[axis]){hits.push(p[1-axis]);hits.push(q[1-axis]);}}else{let t=(station-p[axis])/(q[axis]-p[axis]);if(-1e-8..=1.+1e-8).contains(&t){hits.push(p[1-axis]+t*(q[1-axis]-p[1-axis]));}}}if hits.len()>=2{hits.sort_by(f64::total_cmp);let start=hits[0];let end=*hits.last().unwrap();let mut breaks=vec![start];let mut cut=(start/16.).floor()*16.+16.;while cut<end-1.5{if cut>0.&&cut<if run_x{c.width}else{c.depth}{breaks.push(cut)}cut+=16.;}breaks.push(end);for(part,span)in breaks.windows(2).enumerate(){let at=span[0];let to=span[1];let p=xyz(if run_x{[at,station]}else{[station,at]});let q=xyz(if run_x{[to,station]}else{[station,to]});let length=(to-at)*(1.+a*a+b*b).sqrt();if length>0.1{rafters.push(json!({"id":format!("R{}-{}-{}",i,station,part),"plane":f.p,"x":p[0],"x1":p[0],"x2":q[0],"z1":p[2],"z2":q[2],"y1":p[1],"y2":q[1],"length":length,"stockLength":(length/2.).ceil()*2.,"side":format!("Roof plane {}",i+1),"bay":part+1}));}}}station+=spacing;}
  for j in 0..f.poly.len(){let p=f.poly[j];let q=f.poly[(j+1)%f.poly.len()];let dx=q[0]-p[0];let dz=q[1]-p[1];let sq=dx*dx+dz*dz;if sq<1e-8{continue}let mut ts=vec![0.,1.];for v in &vertices{let t=((v[0]-p[0])*dx+(v[1]-p[1])*dz)/sq;if t>1e-6&&t<1.-1e-6&&((v[0]-p[0])*dz-(v[1]-p[1])*dx).abs()<1e-5{ts.push(t)}}ts.sort_by(f64::total_cmp);ts.dedup_by(|a,b|near(*a,*b));for ab in ts.windows(2){let u=[p[0]+dx*ab[0],p[1]+dz*ab[0]];let v=[p[0]+dx*ab[1],p[1]+dz*ab[1]];let mut keys=[format!("{:.4},{:.4}",u[0],u[1]),format!("{:.4},{:.4}",v[0],v[1])];keys.sort();if !seen.insert(keys.join("/")){continue}let aa=xyz(u);let bb=xyz(v);let length=((aa[0]-bb[0]).powi(2)+(aa[1]-bb[1]).powi(2)+(aa[2]-bb[2]).powi(2)).sqrt();let outer=(near(u[0],-overhang)&&near(v[0],-overhang))||(near(u[0],c.width+overhang)&&near(v[0],c.width+overhang))||(near(u[1],-overhang)&&near(v[1],-overhang))||(near(u[1],c.depth+overhang)&&near(v[1],c.depth+overhang));let kind=if outer{if near(aa[1],bb[1]){eave+=length;"eave"}else{rake+=length;"rake"}}else{let x=(u[0]+v[0])/2.;let z=(u[1]+v[1])/2.;let norm=sq.sqrt();let diff=height(c,x,z)-(height(c,x+dz/norm*0.02,z-dx/norm*0.02)+height(c,x-dz/norm*0.02,z+dx/norm*0.02))/2.;if diff.abs()<1e-6{continue}if architecture::preset(&c.home_style).3=="Gambrel"&&(near(z,c.depth*0.25)||near(z,c.depth*0.75)){hip+=length;"break"}else if diff<0.{valley+=length;"valley"}else if near(aa[1],bb[1]){ridge+=length;"ridge"}else{hip+=length;"hip"}};edges.push(json!({"a":aa,"b":bb,"kind":kind,"length":length}));}}
 }
 rafters=join_rafters(rafters,c);
 let mut support_points:BTreeMap<String,Vec<[f64;3]>>=BTreeMap::new();for r in &rafters{if n(r,"bay")>1.{let x=n(r,"x1");let z=n(r,"z1");let axis=if near(x,n(r,"x2")){format!("z{:.3}",z)}else{format!("x{:.3}",x)};support_points.entry(format!("{}-{}",s(r,"side"),axis)).or_default().push([x,n(r,"y1"),z]);}}let supports:Vec<_>=support_points.values_mut().filter_map(|ps|{ps.sort_by(|a,b|(a[0]+a[2]).total_cmp(&(b[0]+b[2])));if ps.len()<2{return None}let a=ps[0];let b=*ps.last().unwrap();let length=((a[0]-b[0]).powi(2)+(a[2]-b[2]).powi(2)).sqrt();Some(json!({"a":a,"b":b,"length":length,"kind":"intermediate"}))}).collect();let support_lf=supports.iter().map(|v|n(v,"length")).sum::<f64>();let support_posts=supports.iter().chain(edges.iter().filter(|e|["ridge","hip","valley","break"].contains(&s(e,"kind")))).map(|v|(n(v,"length")/16.).ceil()+1.).sum::<f64>();
 let mut ridge_members=vec![];for (edge_index,e) in edges.iter().enumerate().filter(|(_,e)|s(e,"kind")=="ridge"){let a=e["a"].as_array().unwrap();let b=e["b"].as_array().unwrap();let ax=a[0].as_f64().unwrap();let az=a[2].as_f64().unwrap();let bx=b[0].as_f64().unwrap();let bz=b[2].as_f64().unwrap();let len=((bx-ax).powi(2)+(bz-az).powi(2)).sqrt();for ply in 0..4{let offset=(ply as f64-1.5)*1.75/12.;let dx=-(bz-az)/len*offset;let dz=(bx-ax)/len*offset;ridge_members.push(json!({"id":format!("RIDGE-{}-PLY{}",edge_index+1,ply+1),"wallId":"ROOF-RIDGE","role":"LVL ridge ply","material":"LVL · 1¾ in ply, grade/depth pending","group":"Roof framing","x1":ax+dx,"y1":a[1].as_f64().unwrap()-0.8,"z1":az+dz,"x2":bx+dx,"y2":b[1].as_f64().unwrap()-0.8,"z2":bz+dz,"width":1.75/12.,"depth":1.25,"length":len,"stockLength":(len/2.).ceil()*2.,"ply":ply+1,"status":"Schematic 15 in displayed depth; engineering sizing and connections pending"}));}}
 let profiles:Vec<_>=[Wall{id:"E1".into(),name:"".into(),x:0.,z:0.,length:c.width,axis:"x".into(),exterior:true,openings:vec![]},Wall{id:"E2".into(),name:"".into(),x:0.,z:c.depth,length:c.width,axis:"x".into(),exterior:true,openings:vec![]},Wall{id:"E3".into(),name:"".into(),x:0.,z:0.,length:c.depth,axis:"z".into(),exterior:true,openings:vec![]},Wall{id:"E4".into(),name:"".into(),x:c.width,z:0.,length:c.depth,axis:"z".into(),exterior:true,openings:vec![]}].iter().map(|w|json!({"x":w.x,"z":w.z,"axis":w.axis,"points":wall_profile(c,w)})).collect();let infill=profiles.iter().map(|p|p["points"].as_array().unwrap().windows(2).map(|q|(q[1][0].as_f64().unwrap()-q[0][0].as_f64().unwrap())*(q[0][1].as_f64().unwrap()+q[1][1].as_f64().unwrap())/2.).sum::<f64>()).sum::<f64>();
 json!({"ridgeMembers":ridge_members,"ridgeAssembly":{"plies":4,"plyThicknessInches":1.75,"widthInches":7.,"depthStatus":"Engineering selection pending"},"supports":supports,"supportLF":support_lf,"supportPosts":support_posts,"type":architecture::preset(&c.home_style).3,"facets":facets,"edges":edges,"profiles":profiles,"area":area_total,"rise":rise,"infillArea":infill,"ridgeLF":ridge,"hipLF":hip,"valleyLF":valley,"eaveLF":eave,"rakeLF":rake,"rafters":rafters,"note":"I-joist roof concept with four-ply LVL ridge (7 in built width), supported hip, valley and intermediate beams; no compression-rafter or truss assumption. Product sizing, load paths and connections require engineering."})}

// Facet clipping can divide one roof plane into adjacent polygons. Join its
// collinear pieces before counting stock, then split only at support bays.
fn join_rafters(raw:Vec<Value>,c:&Config)->Vec<Value>{
 let mut groups:BTreeMap<String,Vec<Value>>=BTreeMap::new();
 for r in raw{let axis=if near(n(&r,"x1"),n(&r,"x2")){"z"}else{"x"};let station=if axis=="z"{n(&r,"x1")}else{n(&r,"z1")};groups.entry(format!("{}:{:.6}:{}",axis,station,r["plane"])).or_default().push(r);}
 let mut out=vec![];
 for(_,mut rs)in groups{let run_x=!near(n(&rs[0],"x1"),n(&rs[0],"x2"));let key1=if run_x{"x1"}else{"z1"};let key2=if run_x{"x2"}else{"z2"};rs.sort_by(|a,b|n(a,key1).total_cmp(&n(b,key1)));let plane=rs[0]["plane"].clone();let ps=plane.as_array().unwrap();let a=ps[0].as_f64().unwrap();let b=ps[1].as_f64().unwrap();let k=ps[2].as_f64().unwrap();let station=if run_x{n(&rs[0],"z1")}else{n(&rs[0],"x1")};let mut spans:Vec<(f64,f64)>=vec![];
 for r in rs{let start=n(&r,key1);let end=n(&r,key2);if let Some(last)=spans.last_mut(){if start<=last.1+1e-6{last.1=last.1.max(end);continue}}spans.push((start,end));}
 for(start,end)in spans{let mut cuts=vec![start];let mut cut=(start/16.).floor()*16.+16.;while cut<end-1.5{if cut>0.&&cut<if run_x{c.width}else{c.depth}{cuts.push(cut)}cut+=16.;}cuts.push(end);for(i,v)in cuts.windows(2).enumerate(){let x1=if run_x{v[0]}else{station};let z1=if run_x{station}else{v[0]};let x2=if run_x{v[1]}else{station};let z2=if run_x{station}else{v[1]};let y1=c.wall_height+a*x1+b*z1+k;let y2=c.wall_height+a*x2+b*z2+k;let length=((x2-x1).powi(2)+(z2-z1).powi(2)+(y2-y1).powi(2)).sqrt();if length>0.1{out.push(json!({"id":format!("RAFTER-{}",out.len()+1),"plane":plane,"x":x1,"x1":x1,"x2":x2,"z1":z1,"z2":z2,"y1":y1,"y2":y2,"length":length,"stockLength":(length/2.).ceil()*2.,"side":format!("Plane {}",plane),"bay":i+1}));}}}
 }out
}
